CREATE TABLE organizations (id uuid PRIMARY KEY, name text NOT NULL, settings jsonb NOT NULL DEFAULT '{}');
CREATE TABLE users (subject text PRIMARY KEY, email text UNIQUE NOT NULL, name text NOT NULL);
CREATE TABLE memberships (org_id uuid NOT NULL REFERENCES organizations(id), subject text NOT NULL REFERENCES users(subject), role text NOT NULL CHECK(role IN ('admin','member','viewer')), PRIMARY KEY(org_id,subject));
CREATE TABLE enrollments (id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE devices (id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, token_hash text UNIQUE NOT NULL, hostname text NOT NULL, os_version text NOT NULL, agent_version text NOT NULL, last_seen timestamptz, queue_depth integer NOT NULL DEFAULT 0, monitoring_enabled boolean NOT NULL DEFAULT false, consent_version text NOT NULL DEFAULT '', registry_version text NOT NULL DEFAULT '', config_version integer NOT NULL DEFAULT 1, revoked_at timestamptz, UNIQUE(org_id,id));
CREATE TABLE events (org_id uuid NOT NULL, event_id uuid NOT NULL, device_id uuid NOT NULL, payload jsonb NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(org_id,event_id), FOREIGN KEY(org_id,device_id) REFERENCES devices(org_id,id));
CREATE INDEX events_received ON events(org_id, received_at DESC);
CREATE INDEX devices_org ON devices(org_id);
ALTER TABLE organizations ENABLE ROW LEVEL SECURITY;
ALTER TABLE organizations FORCE ROW LEVEL SECURITY;
CREATE POLICY org_scope ON organizations USING (id::text = current_setting('app.org_id',true) OR EXISTS(SELECT 1 FROM memberships WHERE memberships.org_id=organizations.id));
ALTER TABLE users ENABLE ROW LEVEL SECURITY;
ALTER TABLE users FORCE ROW LEVEL SECURITY;
CREATE POLICY user_identity ON users FOR SELECT USING (subject=current_setting('app.subject',true) OR email=current_setting('app.local_email',true));
ALTER TABLE memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE memberships FORCE ROW LEVEL SECURITY;
CREATE POLICY member_identity ON memberships FOR SELECT USING(subject=current_setting('app.subject',true));
ALTER TABLE enrollments ENABLE ROW LEVEL SECURITY;
ALTER TABLE enrollments FORCE ROW LEVEL SECURITY;
CREATE POLICY enrollment_scope ON enrollments USING(org_id::text=current_setting('app.org_id',true) OR token_hash=current_setting('app.enrollment_hash',true)) WITH CHECK(org_id::text=current_setting('app.org_id',true));
ALTER TABLE devices ENABLE ROW LEVEL SECURITY;
ALTER TABLE devices FORCE ROW LEVEL SECURITY;
CREATE POLICY device_scope ON devices USING(org_id::text=current_setting('app.org_id',true) OR token_hash=current_setting('app.device_hash',true)) WITH CHECK(org_id::text=current_setting('app.org_id',true));
ALTER TABLE events ENABLE ROW LEVEL SECURITY;
ALTER TABLE events FORCE ROW LEVEL SECURITY;
CREATE POLICY event_scope ON events USING(org_id::text=current_setting('app.org_id',true)) WITH CHECK(org_id::text=current_setting('app.org_id',true));
REVOKE ALL ON organizations, users, memberships, enrollments, devices, events FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO devise_app;
GRANT SELECT ON organizations, users, memberships TO devise_app;
GRANT SELECT, INSERT, UPDATE ON enrollments, devices TO devise_app;
GRANT SELECT, INSERT, DELETE ON events TO devise_app;
